cards.content:
{% set na = ['unknown','unavailable','none',''] %}
{% set local = states('select.ember_satellite_assistant') == 'familiar-ember' %}{% set up = is_state('binary_sensor.ember_reachable', 'on') %}{% set det = (state_attr('binary_sensor.ember_reachable', 'detail') or '—') | trim %}{% set hushed = is_state('switch.ember_satellite_hush', 'on') %}
{% set pl = states('select.ember_satellite_assistant') %}
{% set chain = {
  'familiar-ember': ['Ember · local Qwen3.6-35B on familiar','vosk','piper','en_GB-cori-medium'],
  'claude-donkee': ['Claude Opus 4.7 · Bedrock','vosk','piper','en_US-hfc_female-medium'],
  'Chatgpt': ['ChatGPT','faster-whisper','piper','en_US-hfc_female-medium'],
  'Gemini-vosk-piper-donkee': ['Google Gemini','vosk','piper','en_US-hfc_female-medium'],
  'yurt-butler': ['Home Assistant','faster-whisper','piper','en_US-hfc_female-medium'],
  'Home Assistant': ['Home Assistant','—','HA Cloud','JennyNeural'],
  'preferred': ['Google Gemini · HA preferred','vosk','piper','en_US-hfc_female-medium']
} %}
{% set p = chain.get(pl, ['—','—','—','—']) %}
{% set held = states.select['ember_satellite_assistant'] %}
{% set since = relative_time(held.last_changed) ~ ' on this pipeline' if held else '—' %}
{% set mind = (det if up else '`' ~ det ~ '`') if local else 'cloud agent · not gated on familiar' %}
| | stage | engine | reading |
|:--|:--|:--|:--|
| ○ | **wake** | openwakeword | {{ 'ready' if states('wake_word.openwakeword') not in na else 'idle' }} |
| ◔ | **ear** | {{ p[1] }} | {% set v = states('sensor.ember_satellite_mic_rms') %}{{ (v | float | round(1)) ~ ' dB' if v not in na else '—' }} |
| {{ '◑' if (up or not local) else '`✖`' }} | **mind** | {{ p[0] }} | {{ mind }} · {{ since }} |
| ◆ | **voice** | {{ p[2] }} · *{{ p[3] }}* | {% set v = states('sensor.ember_satellite_speaker_frames') %}{{ (v | float | int) ~ ' frames' if v not in na else '—' }} |

