style.ha-markdown$:
table { width:100%; border-collapse:collapse; font-size:12.5px; }
th { text-align:left; font-size:10px; letter-spacing:2.5px; text-transform:uppercase;
  color:var(--em-dim); border-bottom:1px solid var(--divider-color); padding:4px 8px; }
td { padding:7px 8px; border-bottom:1px solid
  color-mix(in srgb, var(--divider-color) 42%, transparent);
  color:var(--secondary-text-color); }
strong { color:var(--em-gold); font-weight:600; letter-spacing:.4px; }
em { color:var(--em-tip); font-style:normal; }
code { color:var(--em-glow); background:none; }

td:first-child { color:var(--em-glow); width:22px; font-size:15px; }
/* Backticks are this table's only use of `code`, and they mark the unhealthy
   mind — so repoint code from the shared glow to alarm. */
code { color:var(--em-alarm); font-family:inherit; font-weight:600; }

